import java.io.File;
import java.nio.file.Path;
import java.nio.file.Paths;

public class ImportingUtilities {

    // other methods

    /**
     * Creates a unique file inside {@code dir} using {@code name}.  
     * The method protects against directory‑traversal attacks by ensuring that the
     * resolved path stays within {@code dir}.  Query parameters are stripped,
     * and any attempt to escape the target directory results in an
     * {@link IllegalArgumentException}.
     *
     * @param dir  the base directory where the file should be created
     * @param name the requested file name (may contain path separators)
     * @return a {@link File} instance that does not yet exist
     * @throws IllegalArgumentException if {@code dir} is null, not a directory,
     *                                  or if {@code name} would resolve outside {@code dir}
     */
    static public File allocateFile(File dir, String name) {
        if (dir == null || !dir.isDirectory()) {
            throw new IllegalArgumentException("Target directory is invalid");
        }
        if (name == null) {
            throw new IllegalArgumentException("File name cannot be null");
        }

        // Remove query string if present
        int q = name.indexOf('?');
        if (q > 0) {
            name = name.substring(0, q);
        }

        // Resolve the requested path against the base directory
        Path targetPath = dir.toPath().resolve(name).normalize();

        // Ensure the resolved path is still under the base directory
        Path normalizedDir = dir.toPath().normalize();
        if (!targetPath.startsWith(normalizedDir)) {
            throw new IllegalArgumentException(
                "Attempt to create a file outside the target directory: " + name);
        }

        // Prepare the initial File instance
        File file = targetPath.toFile();

        // Handle duplicate names by appending "-n" before the extension
        int dot = name.lastIndexOf('.');
        String prefix = dot < 0 ? name : name.substring(0, dot);
        String suffix = dot < 0 ? "" : name.substring(dot);
        int index = 2;
        while (file.exists()) {
            file = new File(dir, prefix + "-" + index++ + suffix);
        }

        // Create any missing parent directories
        file.getParentFile().mkdirs();

        return file;
    }

    // other methods
}
