class RgbeInfo implements Closeable {

    private final InputStream in;

    // other methods

    /**
     * Decompresses data from the given {@link InputStream} into the supplied
     * output buffer using a simple run‑length encoding scheme.
     *
     * <p>This implementation performs extensive validation to guard against
     * malformed input that could otherwise cause an infinite loop or
     * buffer overflow.  Each byte read from the stream is treated as an
     * unsigned value.  A value greater than 128 indicates a repeated byte
     * run; otherwise it represents a literal run.  Zero counts are
     * considered invalid and result in an {@link IOException}.</p>
     *
     * @param in  the source stream
     * @param out the destination buffer
     * @throws IOException if the stream ends unexpectedly or the data is
     *                     malformed
     */
    private static void decompress(final InputStream in, final byte[] out) throws IOException {
        int position = 0;
        final int total = out.length;

        while (position < total) {
            int n = in.read();
            if (n == -1) {
                throw new EOFException("Unexpected end of stream while reading control byte");
            }

            if (n > 128) { // repeated byte run
                int value = in.read();
                if (value == -1) {
                    throw new EOFException("Unexpected end of stream while reading repeat value");
                }

                int repeatCount = n & 0x7F;
                if (repeatCount == 0) {
                    throw new IOException("Invalid repeat count of zero");
                }
                if (position + repeatCount > total) {
                    throw new IOException("Repeat run exceeds output buffer size");
                }

                byte val = (byte) value;
                for (int i = 0; i < repeatCount; i++) {
                    out[position++] = val;
                }
            } else { // literal run
                int literalCount = n;
                if (literalCount == 0) {
                    throw new IOException("Invalid literal count of zero");
                }
                if (position + literalCount > total) {
                    throw new IOException("Literal run exceeds output buffer size");
                }

                for (int i = 0; i < literalCount; i++) {
                    int b = in.read();
                    if (b == -1) {
                        throw new EOFException("Unexpected end of stream during literal run");
                    }
                    out[position++] = (byte) b;
                }
            }
        }
    }

    // other methods

    @Override
    public void close() throws IOException {
        in.close();
    }
}
