import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import org.apache.commons.compress.archivers.ArchiveEntry;

public class Expander {

    // other methods

    /**
     * Safely expands archive entries into the target directory.
     *
     * <p>This method performs rigorous validation of each entry name to prevent
     * path‑traversal attacks. It normalizes the resolved path and ensures that
     * the resulting canonical path is a sub‑path of the target directory.
     */
    private void expand(ArchiveEntrySupplier supplier,
                        EntryWriter writer,
                        File targetDirectory) throws IOException {

        // Resolve the canonical path of the target directory once.
        final String targetDirCanonical = targetDirectory.getCanonicalPath();

        ArchiveEntry nextEntry = supplier.getNextReadableEntry();
        while (nextEntry != null) {

            // Reject null or empty entry names early.
            String entryName = nextEntry.getName();
            if (entryName == null || entryName.isEmpty()) {
                throw new IOException("archive entry has no name");
            }

            // Basic sanitisation: disallow absolute paths and
            // any component that could escape the target directory.
            if (!isSafeEntryName(entryName)) {
                throw new IOException("unsafe entry name: " + entryName);
            }

            // Resolve the entry against the target directory and normalise.
            Path resolvedPath = targetDirectory.toPath()
                                               .resolve(entryName)
                                               .normalize();

            // Convert back to File for further operations.
            File f = resolvedPath.toFile();

            // Canonical path check to guard against symlinks / relative components.
            if (!f.getCanonicalPath().startsWith(targetDirCanonical)) {
                throw new IOException(
                        "expanding " + entryName +
                        " would create file outside of " + targetDirectory);
            }

            if (nextEntry.isDirectory()) {
                if (!f.isDirectory() && !f.mkdirs()) {
                    throw new IOException("failed to create directory " + f);
                }
            } else {
                // Ensure parent directories exist.
                File parent = f.getParentFile();
                if (!parent.isDirectory() && !parent.mkdirs()) {
                    throw new IOException("failed to create directory " + parent);
                }

                // Write the entry data.
                try (OutputStream out = Files.newOutputStream(f.toPath())) {
                    writer.writeEntryDataTo(nextEntry, out);
                }
            }

            nextEntry = supplier.getNextReadableEntry();
        }
    }

    /**
     * Validates an archive entry name.
     *
     * @param name the entry name to validate
     * @return true if the name is safe, false otherwise
     */
    private boolean isSafeEntryName(String name) {
        // Reject absolute paths (starting with '/' or drive letter).
        if (name.startsWith("/") || name.startsWith("\\") ||
            name.matches("^[a-zA-Z]:[\\\\/]")) {
            return false;
        }

        // Reject names containing null characters.
        if (name.indexOf('\0') >= 0) {
            return false;
        }

        // Reject names that contain ".." components after normalisation.
        // We perform a quick check here; the canonical path check below
        // provides final assurance.
        if (name.contains("..")) {
            return false;
        }

        return true;
    }

