        if (!Objects.equals(scimUserFromDb.getOrigin(), scimUserFromRequest.getOrigin())) {
            return false;
        }

        return true;
    }

    /**
     * Retrieves the authenticated user ID from the request.  In a typical UAA deployment
     * the principal name corresponds to the user ID.  If no principal is present,
     * {@code null} is returned.
     *
     * @param request the HTTP request
     * @return the authenticated user ID or {@code null}
     */
    private String getAuthenticatedUserId(HttpServletRequest request) {
        Principal principal = request.getUserPrincipal();
        return principal != null ? principal.getName() : null;
    }

